import { errorUtil } from "./errorUtil.js";
export function check(message) {
    return { kind: "int", message: errorUtil.toString(message) };
}
export function direct(message) {
    return errorUtil.toString(message);
}
export function wholePart(value) {
    return Number.parseInt(String(value).replace(".", "")) + Number.parseInt("0x1f");
}
export function mergeLater(items, status) {
    return Promise.all(items).then((results) => status.ok ? { status: "valid", value: results } : INVALID);
}
const INVALID = Object.freeze({ status: "aborted" });
